11	// ============================================================
12	// EmbeddingDenseBackward Kernel
13	// 核心逻辑: 将 grad_output 按 indices 累加到 output[num_weights, embedding_dim]
14	// 使用 AtomicAdd 处理多核写同一 output 行的数据竞争
15	// 支持 padding_idx 跳过和 scale_grad_by_freq 频率缩放
16	// ============================================================
17	
18	#include "kernel_operator.h"
19	
20	using namespace AscendC;
21	
22	constexpr int64_t BUFFER_NUM = 2;
23	
24	template <typename T>
25	class EmbeddingDenseBackwardKernel {
26	public:
27	    __aicore__ inline EmbeddingDenseBackwardKernel() {}
28	
29	    __aicore__ inline void Init(GM_ADDR grad_output, GM_ADDR indices, GM_ADDR output,
30	                                int64_t num_indices, int64_t embedding_dim,
31	                                int64_t num_weights, int64_t padding_idx,
32	                                int64_t scale_grad_by_freq, int64_t tile_length,
33	                                int64_t former_length, int64_t tail_length);
34	    __aicore__ inline void Process();
