37	    __aicore__ inline void CopyIn(int64_t grad_offset, int64_t len);
38	    __aicore__ inline void Compute(int64_t len, float scale);
39	    __aicore__ inline void CopyOut(int64_t output_offset, int64_t len);
40	
41	private:
42	    TPipe pipe;
43	    TQue<TPosition::VECIN, BUFFER_NUM> gradQueue;
44	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;
45	    TBuf<TPosition::VECCALC> castBuf;
46	    TBuf<TPosition::VECCALC> idxBuf;
47	
48	    GlobalTensor<T> gradGm;
49	    GlobalTensor<int32_t> indicesGm;
50	    GlobalTensor<T> outputGm;
51	
52	    int64_t num_indices_ = 0;
53	    int64_t embedding_dim_ = 0;
54	    int64_t num_weights_ = 0;
55	    int64_t padding_idx_ = -1;
56	    int64_t scale_grad_by_freq_ = 0;
57	    int64_t tile_length_ = 0;
58	    int64_t former_length_ = 0;
59	    int64_t tail_length_ = 0;
60	};
61	
62	// =========================== Init ============================
63	
64	template <typename T>
65	__aicore__ inline void EmbeddingDenseBackwardKernel<T>::Init(GM_ADDR grad_output, GM_ADDR indices, GM_ADDR output,
66	                                                               int64_t num_indices, int64_t embedding_dim,
67	                                                               int64_t num_weights, int64_t padding_idx,
68	                                                               int64_t scale_grad_by_freq, int64_t tile_length,
69	                                                               int64_t former_length, int64_t tail_length) {
70	    num_indices_ = num_indices;
71	    embedding_dim_ = embedding_dim;
72	    num_weights_ = num_weights;
73	    padding_idx_ = padding_idx;
74	    scale_grad_by_freq_ = scale_grad_by_freq;
75	    tile_length_ = tile_length;
76	    former_length_ = former_length;
77	    tail_length_ = tail_length;
78	
79	    gradGm.SetGlobalBuffer((__gm__ T*)grad_output, num_indices * embedding_dim);
80	    indicesGm.SetGlobalBuffer((__gm__ int32_t*)indices, num_indices);
81	    outputGm.SetGlobalBuffer((__gm__ T*)output, num_weights * embedding_dim);
82	
83	    // 32字节对齐的tile_length
84	    int64_t dtype_size = sizeof(T);
85	    int64_t align_elems = 32 / dtype_size;
86	    int64_t aligned_tile_length = ((tile_length_ + align_elems - 1) / align_elems) * align_elems;
87	    if (aligned_tile_length == 0) aligned_tile_length = align_elems;
88	
89	    pipe.InitBuffer(gradQueue, BUFFER_NUM, aligned_tile_length * dtype_size);
90	    pipe.InitBuffer(outQueue, BUFFER_NUM, aligned_tile_length * dtype_size);
91	    pipe.InitBuffer(idxBuf, 32); // 32 bytes for index buffer
92	
93	    if constexpr (sizeof(T) != sizeof(float)) {
94	        pipe.InitBuffer(castBuf, aligned_tile_length * sizeof(float));
95	    }
96	}
97	
98	// =========================== CopyIn ============================
99	
100	template <typename T>
101	__aicore__ inline void EmbeddingDenseBackwardKernel<T>::CopyIn(int64_t grad_offset, int64_t len) {
102	    LocalTensor<T> gradLocal = gradQueue.AllocTensor<T>();
103	
104	    DataCopyExtParams copyParams;
105	    copyParams.blockCount = 1;
106	    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
107	    copyParams.srcStride = 0;
108	    copyParams.dstStride = 0;
109	
110	    DataCopyPadExtParams<T> padParams;
111	    padParams.isPad = false;
112	
113	    DataCopyPad(gradLocal, gradGm[grad_offset], copyParams, padParams);
114	    gradQueue.EnQue(gradLocal);
115	}
116	
117	// =========================== Compute ============================
118	
119	template <typename T>
120	__aicore__ inline void EmbeddingDenseBackwardKernel<T>::Compute(int64_t len, float scale) {
121	    LocalTensor<T> gradLocal = gradQueue.DeQue<T>();
122	    LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
123	
124	    if (scale_grad_by_freq_ > 0 && scale != 1.0f) {
125	        if constexpr (sizeof(T) == sizeof(float)) {
126	            // FP32: 直接缩放
127	            Muls(outLocal, gradLocal, scale, len);
128	        } else {
129	            // FP16/BF16: 升精度→缩放→降精度
130	            LocalTensor<float> gradFp32 = castBuf.Get<float>();
131	            LocalTensor<float> outFp32 = castBuf.Get<float>();
132	            Cast(gradFp32, gradLocal, RoundMode::CAST_NONE, len);
133	            Muls(outFp32, gradFp32, scale, len);
134	            Cast(outLocal, outFp32, RoundMode::CAST_ROUND, len);
135	        }
136	    } else {
137	        // 无缩放，直接复制
138	        DataCopy(outLocal, gradLocal, len);
139	    }
140	
141	    gradQueue.FreeTensor(gradLocal);
142	    outQueue.EnQue(outLocal);
143	}
144	
145	// =========================== CopyOut (AtomicAdd) ============================
146	
147	template <typename T>
148	__aicore__ inline void EmbeddingDenseBackwardKernel<T>::CopyOut(int64_t output_offset, int64_t len) {
149	    LocalTensor<T> outLocal = outQueue.DeQue<T>();
150	
151	    DataCopyExtParams copyParams;
152	    copyParams.blockCount = 1;
153	    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
154	    copyParams.srcStride = 0;
155	    copyParams.dstStride = 0;
156	
157	    // 使用 AtomicAdd 累加到 output
158	    SetAtomicAdd<T>();
159	    DataCopyPad(outputGm[output_offset], outLocal, copyParams);
160	    SetAtomicNone();
161	
162	    outQueue.FreeTensor(outLocal);
163	}
164	
165	// =========================== Process ============================
166	
167	template <typename T>
168	__aicore__ inline void EmbeddingDenseBackwardKernel<T>::Process() {
169	    int64_t block_idx = GetBlockIdx();
170	    int64_t core_length = block_idx < (num_indices_ - tail_length_) / former_length_ ? former_length_ : tail_length_;
171	
172	    // 计算当前核处理的索引行范围
173	    int64_t row_offset = 0;
174	    if (block_idx < (num_indices_ - tail_length_) / former_length_) {
175	        row_offset = block_idx * former_length_;
176	    } else {
177	        int64_t former_num = (num_indices_ - tail_length_) / former_length_;
178	        row_offset = former_num * former_length_ + (block_idx - former_num) * tail_length_;
179	    }
180	
181	    if (row_offset >= num_indices_) {
182	        return;
183	    }
184	
185	    int64_t end_row = row_offset + core_length;
186	    if (end_row > num_indices_) {
187	        end_row = num_indices_;
188	    }
189	
190	    // 处理每行索引 - 使用DataCopy将indices读取到UB，避免直接使用GetValue
191	    for (int64_t i = row_offset; i < end_row; ++i) {
192	        // 将当前索引值复制到UB
193	        LocalTensor<int32_t> idxLocal = idxBuf.Get<int32_t>();
194	
195	        DataCopyExtParams idxCopyParams;
196	        idxCopyParams.blockCount = 1;
197	        idxCopyParams.blockLen = sizeof(int32_t);
198	        idxCopyParams.srcStride = 0;
199	        idxCopyParams.dstStride = 0;
200	        DataCopyPadExtParams<int32_t> idxPadParams;
201	        idxPadParams.isPad = false;
202	        DataCopyPad(idxLocal, indicesGm[i], idxCopyParams, idxPadParams);
203	
204	        int32_t idx = idxLocal.GetValue(0);
205	
206	        // 跳过 padding_idx
207	        if (padding_idx_ >= 0 && idx == padding_idx_) {
208	            continue;
209	        }
210	
211	        // 检查索引越界
212	        if (idx < 0 || idx >= num_weights_) {
213	            continue;
214	        }
215	
216	        int64_t grad_offset = i * embedding_dim_;
217	        int64_t output_offset = idx * embedding_dim_;
218	
219	        // 按 embedding_dim 分块处理
220	        int64_t tile_num = (embedding_dim_ + tile_length_ - 1) / tile_length_;
221	        int64_t tail_tile_length = embedding_dim_ - (tile_num - 1) * tile_length_;
222	
223	        for (int64_t t = 0; t < tile_num; ++t) {
224	            int64_t cur_tile_length = (t == tile_num - 1) ? tail_tile_length : tile_length_;
225	
226	            CopyIn(grad_offset + t * tile_length_, cur_tile_length);
227	            Compute(cur_tile_length, 1.0f);
228	            CopyOut(output_offset + t * tile_length_, cur_tile_length);
229	        }
230	    }
231	}
