240	    if (num_indices > 0 && embedding_dim > 0) {
241	        EmbeddingDenseBackwardKernel<half> op;
242	        op.Init(grad_output, indices, output, num_indices, embedding_dim, num_weights,
243	                padding_idx, scale_grad_by_freq, tile_length, former_length, tail_length);
