11	// ============================================================
12	// EmbeddingDenseBackward Host端实现
13	// 负责: 输入校验、输出初始化、tiling计算、kernel启动
14	// ============================================================
15	
16	#include "torch_kernel_helper.h"
17	#include "aclrtlaunch_embedding_dense_backward.h"
18	#include <torch/extension.h>
19	#include "tiling/platform/platform_ascendc.h"
20	
21	namespace ascend_kernel {
22	
23	at::Tensor embedding_dense_backward(const at::Tensor& grad_output,
24	                                     const at::Tensor& indices,
25	                                     int64_t num_weights,
26	                                     int64_t padding_idx,
27	                                     bool scale_grad_by_freq) {
28	    // ---- 输入校验 ----
29	    TORCH_CHECK(grad_output.device().type() == at::DeviceType::PrivateUse1,
30	                "embedding_dense_backward: grad_output must be on NPU device");
31	    TORCH_CHECK(indices.device().type() == at::DeviceType::PrivateUse1,
32	                "embedding_dense_backward: indices must be on NPU device");
33	    TORCH_CHECK(num_weights > 0,
34	                "embedding_dense_backward: num_weights must be > 0");
35	    TORCH_CHECK(grad_output.scalar_type() == at::kFloat ||
36	                grad_output.scalar_type() == at::kHalf ||
37	                grad_output.scalar_type() == at::kBFloat16,
38	                "embedding_dense_backward: only float32, float16 and bfloat16 are supported");
39	    TORCH_CHECK(indices.scalar_type() == at::kLong,
40	                "embedding_dense_backward: indices must be int64");
41	
42	    // ---- 连续化 ----
43	    at::Tensor grad_output_contiguous = grad_output.contiguous();
44	    at::Tensor indices_contiguous = indices.contiguous();
45	
46	    // ---- 维度计算 ----
47	    int64_t num_indices = indices_contiguous.numel();
48	    int64_t embedding_dim = grad_output_contiguous.size(-1);
49	    int64_t dtype_size = grad_output_contiguous.element_size();
50	
51	    // ---- 输出初始化 (zeros) ----
52	    auto output = at::zeros({num_weights, embedding_dim}, grad_output_contiguous.options());
53	
54	    if (num_indices == 0 || embedding_dim == 0) {
55	        return output;
56	    }
57	
58	    // ---- Index 转 int32 ----
59	    auto indices_int32 = indices_contiguous.to(at::kInt);
60	
61	    // ---- 获取平台信息 ----
62	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
63	    int64_t core_num = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
64	    uint64_t ub_size = 0;
65	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ub_size);
66	
67	    // ---- Block级 Tiling: 按索引行分配 ----
68	    int64_t used_core_num = num_indices < core_num ? num_indices : core_num;
69	    if (used_core_num < 1) used_core_num = 1;
70	
71	    int64_t former_num = used_core_num - 1;
72	    int64_t tail_num = 1;
73	    int64_t former_length = (num_indices + used_core_num - 1) / used_core_num;
74	    int64_t tail_length = num_indices - former_num * former_length;
75	    if (tail_length < 0) {
76	        tail_length = former_length;
77	        former_num = used_core_num - 1;
78	    }
79	    if (tail_length == 0 && former_num > 0) {
80	        tail_length = former_length;
81	    }
82	
83	    // ---- UB级 Tiling: 按 embedding_dim 分块 ----
84	    int64_t buffer_coefficient = (dtype_size == 4) ? 8 : 8;
85	    int64_t max_tile_elements = static_cast<int64_t>(ub_size) / buffer_coefficient;
86	    int64_t align_elements = 32 / dtype_size;
87	    int64_t tile_length = (max_tile_elements / align_elements) * align_elements;
88	    if (tile_length > embedding_dim) {
89	        tile_length = embedding_dim;
90	    }
91	    if (tile_length < align_elements) {
92	        tile_length = align_elements;
93	    }
94	
95	    // ---- 构建 EXEC_KERNEL_CMD 参数 (全部左值) ----
96	    int64_t num_indices_val = num_indices;
97	    int64_t embedding_dim_val = embedding_dim;
98	    int64_t num_weights_val = num_weights;
99	    int64_t padding_idx_val = padding_idx;
100	    int64_t scale_grad_val = scale_grad_by_freq ? 1 : 0;
101	    int64_t tile_length_val = tile_length;
102	    int64_t former_length_val = former_length;
103	    int64_t tail_length_val = tail_length;
104	
105	    uint32_t block_dim = static_cast<uint32_t>(used_core_num);
106	    if (block_dim < 1) block_dim = 1;
107	
108	    // ---- 根据 dtype 选择 kernel 入口 ----
109	    if (grad_output.scalar_type() == at::kHalf) {
110	        EXEC_KERNEL_CMD(embedding_dense_backward_half, block_dim,
111	                        grad_output_contiguous, indices_int32, output,
112	                        num_indices_val, embedding_dim_val, num_weights_val,
113	                        padding_idx_val, scale_grad_val, tile_length_val,
114	                        former_length_val, tail_length_val);
115	    } else if (grad_output.scalar_type() == at::kFloat) {
116	        EXEC_KERNEL_CMD(embedding_dense_backward_float, block_dim,
117	                        grad_output_contiguous, indices_int32, output,
118	                        num_indices_val, embedding_dim_val, num_weights_val,
119	                        padding_idx_val, scale_grad_val, tile_length_val,
120	                        former_length_val, tail_length_val);
121	    } else if (grad_output.scalar_type() == at::kBFloat16) {
122	        EXEC_KERNEL_CMD(embedding_dense_backward_bfloat16, block_dim,
123	                        grad_output_contiguous, indices_int32, output,
124	                        num_indices_val, embedding_dim_val, num_weights_val,
125	                        padding_idx_val, scale_grad_val, tile_length_val,
126	                        former_length_val, tail_length_val);
127	    }
128	
129	    return output;
130	}
