// ============================================================
// EmbeddingDenseBackward Host端实现
// 负责: 输入校验、输出初始化、tiling计算、kernel启动、频率缩放后处理
// ============================================================

#include "torch_kernel_helper.h"
#include "aclrtlaunch_embedding_dense_backward.h"
#include <torch/extension.h>
#include "tiling/platform/platform_ascendc.h"

namespace ascend_kernel {

at::Tensor embedding_dense_backward(const at::Tensor& grad_output,
                                     const at::Tensor& indices,
                                     int64_t num_weights,
                                     int64_t padding_idx,
                                     bool scale_grad_by_freq) {
    // ---- 输入校验 ----
    TORCH_CHECK(grad_output.device().type() == at::DeviceType::PrivateUse1,
                "embedding_dense_backward: grad_output must be on NPU device");
    TORCH_CHECK(indices.device().type() == at::DeviceType::PrivateUse1,
                "embedding_dense_backward: indices must be on NPU device");
    TORCH_CHECK(num_weights > 0,
                "embedding_dense_backward: num_weights must be > 0");
    TORCH_CHECK(grad_output.scalar_type() == at::kFloat ||
                grad_output.scalar_type() == at::kHalf ||
                grad_output.scalar_type() == at::kBFloat16,
                "embedding_dense_backward: only float32, float16 and bfloat16 are supported");
    TORCH_CHECK(indices.scalar_type() == at::kLong,
                "embedding_dense_backward: indices must be int64");

    // ---- 连续化 ----
    at::Tensor grad_output_contiguous = grad_output.contiguous();
    at::Tensor indices_contiguous = indices.contiguous();

    // ---- 维度计算 ----
    int64_t num_indices = indices_contiguous.numel();
    int64_t embedding_dim = grad_output_contiguous.size(-1);
    int64_t dtype_size = grad_output_contiguous.element_size();

    // ---- 输出初始化 (zeros) ----
    auto output = at::zeros({num_weights, embedding_dim}, grad_output_contiguous.options());

    if (num_indices == 0 || embedding_dim == 0) {
        return output;
    }

    // ---- Index 转 int32 ----
    auto indices_int32 = indices_contiguous.to(at::kInt);

    // ---- 获取平台信息 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t core_num = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ub_size = 0;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ub_size);

    // ---- Block级 Tiling: 按索引行分配 ----
    int64_t used_core_num = num_indices < core_num ? num_indices : core_num;
    if (used_core_num < 1) used_core_num = 1;

    int64_t former_num = used_core_num - 1;
    int64_t tail_num = 1;
    int64_t former_length = (num_indices + used_core_num - 1) / used_core_num;
    int64_t tail_length = num_indices - former_num * former_length;
    if (tail_length < 0) {
        tail_length = former_length;
        former_num = used_core_num - 1;
    }
    if (tail_length == 0 && former_num > 0) {
        tail_length = former_length;
    }

    // ---- UB级 Tiling: 按 embedding_dim 分块 ----
    int64_t buffer_coefficient = (dtype_size == 4) ? 16 : 16;
    int64_t max_tile_elements = static_cast<int64_t>(ub_size) / buffer_coefficient;
    int64_t align_elements = 32 / dtype_size;
    int64_t tile_length = (max_tile_elements / align_elements) * align_elements;
    if (tile_length > embedding_dim) {
        tile_length = embedding_dim;
    }
    if (tile_length < align_elements) {
        tile_length = align_elements;
    }

    // ---- 构建 EXEC_KERNEL_CMD 参数 (全部左值) ----
    int64_t num_indices_val = num_indices;
    int64_t embedding_dim_val = embedding_dim;
    int64_t num_weights_val = num_weights;
    int64_t padding_idx_val = padding_idx;
    int64_t scale_grad_val = scale_grad_by_freq ? 1 : 0;
    int64_t tile_length_val = tile_length;
    int64_t former_length_val = former_length;
    int64_t tail_length_val = tail_length;

    uint32_t block_dim = static_cast<uint32_t>(used_core_num);
    if (block_dim < 1) block_dim = 1;

    // ---- 根据 dtype 选择 kernel 入口 ----
    if (grad_output.scalar_type() == at::kHalf) {
        EXEC_KERNEL_CMD(embedding_dense_backward_half, block_dim,
                        grad_output_contiguous, indices_int32, output,
                        num_indices_val, embedding_dim_val, num_weights_val,
                        padding_idx_val, scale_grad_val, tile_length_val,
                        former_length_val, tail_length_val);
    } else if (grad_output.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(embedding_dense_backward_float, block_dim,
                        grad_output_contiguous, indices_int32, output,
                        num_indices_val, embedding_dim_val, num_weights_val,
                        padding_idx_val, scale_grad_val, tile_length_val,
                        former_length_val, tail_length_val);
    } else if (grad_output.scalar_type() == at::kBFloat16) {
        EXEC_KERNEL_CMD(embedding_dense_backward_bfloat16, block_dim,
                        grad_output_contiguous, indices_int32, output,
                        num_indices_val, embedding_dim_val, num_weights_val,
                        padding_idx_val, scale_grad_val, tile_length_val,
                        former_length_val, tail_length_val);
    }

    // ---- 频率缩放后处理 ----
    if (scale_grad_by_freq) {
        // 统计每个索引出现次数
        auto counts = at::zeros({num_weights}, indices_int32.options());
        auto ones = at::ones_like(indices_int32);
        counts = counts.index_add(0, indices_int32, ones);

        // 转为与output相同dtype，安全除零处理
        auto counts_f = counts.to(output.scalar_type()).unsqueeze(1);
        counts_f = counts_f.clamp_min(1.0f);

        // output /= counts_f (按行广播)
        output = output.div(counts_f);
    }

    return output;
}

}  // namespace ascend_kernel
