// ============================================================
// EmbeddingDenseBackward Kernel
// 核心逻辑: 将 grad_output 按 indices 累加到 output[num_weights, embedding_dim]
// 使用 AtomicAdd 处理多核写同一 output 行的数据竞争
// 支持 padding_idx 跳过（频率缩放在 Host 端后处理）
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

template <typename T>
class EmbeddingDenseBackwardKernel {
public:
    __aicore__ inline EmbeddingDenseBackwardKernel() {}

    __aicore__ inline void Init(GM_ADDR grad_output, GM_ADDR indices, GM_ADDR output,
                                int64_t num_indices, int64_t embedding_dim,
                                int64_t num_weights, int64_t padding_idx,
                                int64_t scale_grad_by_freq, int64_t tile_length,
                                int64_t former_length, int64_t tail_length);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t grad_offset, int64_t len);
    __aicore__ inline void Compute(int64_t len);
    __aicore__ inline void CopyOut(int64_t output_offset, int64_t len);

private:
    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> gradQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;
    TBuf<TPosition::VECCALC> castBuf;
    TBuf<TPosition::VECCALC> idxBuf;

    GlobalTensor<T> gradGm;
    GlobalTensor<int32_t> indicesGm;
    GlobalTensor<T> outputGm;

    int64_t num_indices_ = 0;
    int64_t embedding_dim_ = 0;
    int64_t num_weights_ = 0;
    int64_t padding_idx_ = -1;
    int64_t scale_grad_by_freq_ = 0;
    int64_t tile_length_ = 0;
    int64_t former_length_ = 0;
    int64_t tail_length_ = 0;
};

// =========================== Init ============================

template <typename T>
__aicore__ inline void EmbeddingDenseBackwardKernel<T>::Init(GM_ADDR grad_output, GM_ADDR indices, GM_ADDR output,
                                                               int64_t num_indices, int64_t embedding_dim,
                                                               int64_t num_weights, int64_t padding_idx,
                                                               int64_t scale_grad_by_freq, int64_t tile_length,
                                                               int64_t former_length, int64_t tail_length) {
    num_indices_ = num_indices;
    embedding_dim_ = embedding_dim;
    num_weights_ = num_weights;
    padding_idx_ = padding_idx;
    scale_grad_by_freq_ = scale_grad_by_freq;
    tile_length_ = tile_length;
    former_length_ = former_length;
    tail_length_ = tail_length;

    gradGm.SetGlobalBuffer((__gm__ T*)grad_output, num_indices * embedding_dim);
    indicesGm.SetGlobalBuffer((__gm__ int32_t*)indices, num_indices);
    outputGm.SetGlobalBuffer((__gm__ T*)output, num_weights * embedding_dim);

    // 32字节对齐的tile_length
    int64_t dtype_size = sizeof(T);
    int64_t align_elems = 32 / dtype_size;
    int64_t aligned_tile_length = ((tile_length_ + align_elems - 1) / align_elems) * align_elems;
    if (aligned_tile_length == 0) aligned_tile_length = align_elems;

    pipe.InitBuffer(gradQueue, BUFFER_NUM, aligned_tile_length * dtype_size);
    pipe.InitBuffer(outQueue, BUFFER_NUM, aligned_tile_length * dtype_size);
    pipe.InitBuffer(idxBuf, 32);

    if constexpr (sizeof(T) != sizeof(float)) {
        pipe.InitBuffer(castBuf, aligned_tile_length * sizeof(float));
    }
}

// =========================== CopyIn ============================

template <typename T>
__aicore__ inline void EmbeddingDenseBackwardKernel<T>::CopyIn(int64_t grad_offset, int64_t len) {
    LocalTensor<T> gradLocal = gradQueue.AllocTensor<T>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;

    DataCopyPadExtParams<T> padParams;
    padParams.isPad = false;

    DataCopyPad(gradLocal, gradGm[grad_offset], copyParams, padParams);
    gradQueue.EnQue(gradLocal);
}

// =========================== Compute ============================

template <typename T>
__aicore__ inline void EmbeddingDenseBackwardKernel<T>::Compute(int64_t len) {
    LocalTensor<T> gradLocal = gradQueue.DeQue<T>();
    LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

    // 直接透传数据（不做频率缩放，缩放由Host端后处理完成）
    DataCopy(outLocal, gradLocal, len);

    gradQueue.FreeTensor(gradLocal);
    outQueue.EnQue(outLocal);
}

// =========================== CopyOut (AtomicAdd) ============================

template <typename T>
__aicore__ inline void EmbeddingDenseBackwardKernel<T>::CopyOut(int64_t output_offset, int64_t len) {
    LocalTensor<T> outLocal = outQueue.DeQue<T>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;

    // 使用 AtomicAdd 累加到 output
    SetAtomicAdd<T>();
    DataCopyPad(outputGm[output_offset], outLocal, copyParams);
    SetAtomicNone();

    outQueue.FreeTensor(outLocal);
}

// =========================== Process ============================

template <typename T>
__aicore__ inline void EmbeddingDenseBackwardKernel<T>::Process() {
    int64_t block_idx = GetBlockIdx();
    int64_t core_length = block_idx < (num_indices_ - tail_length_) / former_length_ ? former_length_ : tail_length_;

    // 计算当前核处理的索引行范围
    int64_t row_offset = 0;
    if (block_idx < (num_indices_ - tail_length_) / former_length_) {
        row_offset = block_idx * former_length_;
    } else {
        int64_t former_num = (num_indices_ - tail_length_) / former_length_;
        row_offset = former_num * former_length_ + (block_idx - former_num) * tail_length_;
    }

    if (row_offset >= num_indices_) {
        return;
    }

    int64_t end_row = row_offset + core_length;
    if (end_row > num_indices_) {
        end_row = num_indices_;
    }

    // 处理每行索引
    for (int64_t i = row_offset; i < end_row; ++i) {
        // 将当前索引值复制到UB
        LocalTensor<int32_t> idxLocal = idxBuf.Get<int32_t>();

        DataCopyExtParams idxCopyParams;
        idxCopyParams.blockCount = 1;
        idxCopyParams.blockLen = sizeof(int32_t);
        idxCopyParams.srcStride = 0;
        idxCopyParams.dstStride = 0;
        DataCopyPadExtParams<int32_t> idxPadParams;
        idxPadParams.isPad = false;
        DataCopyPad(idxLocal, indicesGm[i], idxCopyParams, idxPadParams);

        int32_t idx = idxLocal.GetValue(0);

        // 跳过 padding_idx
        if (padding_idx_ >= 0 && idx == padding_idx_) {
            continue;
        }

        // 检查索引越界
        if (idx < 0 || idx >= num_weights_) {
            continue;
        }

        int64_t grad_offset = i * embedding_dim_;
        int64_t output_offset = idx * embedding_dim_;

        // 按 embedding_dim 分块处理
        int64_t tile_num = (embedding_dim_ + tile_length_ - 1) / tile_length_;
        int64_t tail_tile_length = embedding_dim_ - (tile_num - 1) * tile_length_;

        for (int64_t t = 0; t < tile_num; ++t) {
            int64_t cur_tile_length = (t == tile_num - 1) ? tail_tile_length : tile_length_;

            CopyIn(grad_offset + t * tile_length_, cur_tile_length);
            Compute(cur_tile_length);
            CopyOut(output_offset + t * tile_length_, cur_tile_length);
        }
    }
}

// =========================== Kernel Entry (half) ============================

extern "C" __global__ __aicore__ void embedding_dense_backward_half(GM_ADDR grad_output, GM_ADDR indices, GM_ADDR output,
                                                                 int64_t num_indices, int64_t embedding_dim,
                                                                 int64_t num_weights, int64_t padding_idx,
                                                                 int64_t scale_grad_by_freq, int64_t tile_length,
                                                                 int64_t former_length, int64_t tail_length) {
    if (num_indices > 0 && embedding_dim > 0) {
        EmbeddingDenseBackwardKernel<half> op;
        op.Init(grad_output, indices, output, num_indices, embedding_dim, num_weights,
                padding_idx, scale_grad_by_freq, tile_length, former_length, tail_length);
        op.Process();
    }
}

// =========================== Kernel Entry (float) ============================

extern "C" __global__ __aicore__ void embedding_dense_backward_float(GM_ADDR grad_output, GM_ADDR indices, GM_ADDR output,
                                                                 int64_t num_indices, int64_t embedding_dim,
                                                                 int64_t num_weights, int64_t padding_idx,
                                                                 int64_t scale_grad_by_freq, int64_t tile_length,
                                                                 int64_t former_length, int64_t tail_length) {
    if (num_indices > 0 && embedding_dim > 0) {
        EmbeddingDenseBackwardKernel<float> op;
        op.Init(grad_output, indices, output, num_indices, embedding_dim, num_weights,
                padding_idx, scale_grad_by_freq, tile_length, former_length, tail_length);
        op.Process();
    }
}

// =========================== Kernel Entry (bfloat16) ============================

extern "C" __global__ __aicore__ void embedding_dense_backward_bfloat16(GM_ADDR grad_output, GM_ADDR indices, GM_ADDR output,
                                                                 int64_t num_indices, int64_t embedding_dim,
                                                                 int64_t num_weights, int64_t padding_idx,
                                                                 int64_t scale_grad_by_freq, int64_t tile_length,
                                                                 int64_t former_length, int64_t tail_length) {
    if (num_indices > 0 && embedding_dim > 0) {
        EmbeddingDenseBackwardKernel<bfloat16_t> op;
        op.Init(grad_output, indices, output, num_indices, embedding_dim, num_weights,
                padding_idx, scale_grad_by_freq, tile_length, former_length, tail_length);
        op.Process();
    }
}
